files.style.css:
* { box-sizing: border-box; }
body {
  margin: 0;
  padding: 24px 16px;
  min-height: 100vh;
  font: 16px/1.5 system-ui, sans-serif;
  color: #243447;
  background: #edf5f2;
}
.sheet {
  max-width: 420px;
  margin: 0 auto;
  padding: 22px;
  border: 1px solid #cddfd8;
  border-radius: 14px;
  background: #fff;
}
h1 { margin: 0 0 .5em; font-size: 1.5rem; line-height: 1.25; }
h2 { font-size: 1.125rem; }
p, ul, figure { margin: .6em 0; }
button, input { font: inherit; }
button { cursor: pointer; }
a { color: #125a46; }
.gallery { width: min(260px, 100%); }
.gallery article {
  padding: 12px;
  border-radius: 8px;
  background: #e2f1eb;
}

.gallery {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px 6px;
}

* { box-sizing: border-box; }
body { margin: 0; padding: 20px 14px; background: #edf5f2; color: #243447; font: 16px/1.6 system-ui, sans-serif; }
.sheet { max-width: 760px; margin: 0 auto; padding: 20px; border-radius: 12px; background: white; }
h1 { margin: 0 0 .5em; font-size: 1.5rem; line-height: 1.3; }
button, input, select, textarea { font: inherit; }
button { cursor: pointer; }
img { max-width: 100%; height: auto; }
a { color: #125a46; }

.card {
  padding: 12px;
  border-radius: 8px;
  background: #eaf4f0;
}
.card h2 { margin: 0 0 .35em; font-size: 1.05rem; }
.card p { margin: 0; }

.route-board {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}
.route-notice { background: #fff1cf; }

/* 在下面编写本关样式。 */

.route-notice {
  grid-column: span 1;
}

